/* eslint-disable space-in-parens */

import Complex64Array = require( '@stdlib/array/complex64' );
import cany = require( './index' );


// TESTS //

// The function returns a boolean...
{
	const x = new Complex64Array( 10 );

	cany( x.length, x, 1 ); // $ExpectType boolean
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Complex64Array( 10 );

	cany( '10', x, 1 ); // $ExpectError
	cany( true, x, 1 ); // $ExpectError
	cany( false, x, 1 ); // $ExpectError
	cany( null, x, 1 ); // $ExpectError
	cany( undefined, x, 1 ); // $ExpectError
	cany( [], x, 1 ); // $ExpectError
	cany( {}, x, 1 ); // $ExpectError
	cany( ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Complex64Array...
{
	const x = new Complex64Array( 10 );

	cany( x.length, '10', 1 ); // $ExpectError
	cany( x.length, true, 1 ); // $ExpectError
	cany( x.length, false, 1 ); // $ExpectError
	cany( x.length, null, 1 ); // $ExpectError
	cany( x.length, undefined, 1 ); // $ExpectError
	cany( x.length, [], 1 ); // $ExpectError
	cany( x.length, {}, 1 ); // $ExpectError
	cany( x.length, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Complex64Array( 10 );

	cany( x.length, x, '1' ); // $ExpectError
	cany( x.length, x, true ); // $ExpectError
	cany( x.length, x, false ); // $ExpectError
	cany( x.length, x, null ); // $ExpectError
	cany( x.length, x, undefined ); // $ExpectError
	cany( x.length, x, [] ); // $ExpectError
	cany( x.length, x, {} ); // $ExpectError
	cany( x.length, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex64Array( 10 );

	cany(); // $ExpectError
	cany( x.length ); // $ExpectError
	cany( x.length, x ); // $ExpectError
	cany( x.length, x, 1, {} ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a boolean...
{
	const x = new Complex64Array( 10 );

	cany.ndarray( x.length, x, 1, 0 ); // $ExpectType boolean
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex64Array( 10 );

	cany.ndarray( '10', x, 1, 0 ); // $ExpectError
	cany.ndarray( true, x, 1, 0 ); // $ExpectError
	cany.ndarray( false, x, 1, 0 ); // $ExpectError
	cany.ndarray( null, x, 1, 0 ); // $ExpectError
	cany.ndarray( undefined, x, 1, 0 ); // $ExpectError
	cany.ndarray( [], x, 1, 0 ); // $ExpectError
	cany.ndarray( {}, x, 1, 0 ); // $ExpectError
	cany.ndarray( ( x: number ): number => x, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex64Array...
{
	const x = new Complex64Array( 10 );

	cany.ndarray( x.length, '10', 1, 0 ); // $ExpectError
	cany.ndarray( x.length, true, 1, 0 ); // $ExpectError
	cany.ndarray( x.length, false, 1, 0 ); // $ExpectError
	cany.ndarray( x.length, null, 1, 0 ); // $ExpectError
	cany.ndarray( x.length, undefined, 1, 0 ); // $ExpectError
	cany.ndarray( x.length, [], 1, 0 ); // $ExpectError
	cany.ndarray( x.length, {}, 1, 0 ); // $ExpectError
	cany.ndarray( x.length, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const x = new Complex64Array( 10 );

	cany.ndarray( x.length, x, '1', 0 ); // $ExpectError
	cany.ndarray( x.length, x, true, 0 ); // $ExpectError
	cany.ndarray( x.length, x, false, 0 ); // $ExpectError
	cany.ndarray( x.length, x, null, 0 ); // $ExpectError
	cany.ndarray( x.length, x, undefined, 0 ); // $ExpectError
	cany.ndarray( x.length, x, [], 0 ); // $ExpectError
	cany.ndarray( x.length, x, {}, 0 ); // $ExpectError
	cany.ndarray( x.length, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const x = new Complex64Array( 10 );

	cany.ndarray( x.length, x, 1, '0' ); // $ExpectError
	cany.ndarray( x.length, x, 1, true ); // $ExpectError
	cany.ndarray( x.length, x, 1, false ); // $ExpectError
	cany.ndarray( x.length, x, 1, null ); // $ExpectError
	cany.ndarray( x.length, x, 1, undefined ); // $ExpectError
	cany.ndarray( x.length, x, 1, [] ); // $ExpectError
	cany.ndarray( x.length, x, 1, {} ); // $ExpectError
	cany.ndarray( x.length, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex64Array( 10 );

	cany.ndarray(); // $ExpectError
	cany.ndarray( x.length ); // $ExpectError
	cany.ndarray( x.length, x ); // $ExpectError
	cany.ndarray( x.length, x, 1 ); // $ExpectError
	cany.ndarray( x.length, x, 1, 0, {} ); // $ExpectError
}
